INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-gran-carrera-de-mimica-scout', 'La Gran Carrera de Mímica Scout', 'Dinámica de relevos no verbales y expresión corporal donde los scouts compiten adivinando acciones dramatizadas mediante mímica pura.', '<h2>📜 Descripción de La Gran Carrera de Mímica Scout</h2>
<p><b>La Gran Carrera de Mímica Scout</b> es una dinámica de velocidad adaptativa, expresión kinésica y deducción en equipo. Organizadas en hileras paralelas tras la línea de salida, las patrullas compiten en modo de posta dramática. El primer corredor corre hacia el dirigente ubicado al frente, lee una tarjeta con una acción secreta (ej. <i>''Un scout intentando armar una carpa en medio de un ventarrón''</i>) y regresa corriendo hacia su equipo para interpretarla en silencio mediante mímica kinésica. Una vez que su patrulla adivina la escena exacta, el siguiente corredor sale disparado a buscar su propia tarjeta.</p>
<p>Esta actividad estimula el lenguaje no verbal, la desinhibición social y la rápida comprensión en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega La Gran Carrera de Mímica Scout?</h2>
<p>Para llevar a cabo la dinámica con dinamismo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Alineación de Patrullas:</b> Se forman las seisenas tras la línea de partida en el salón o patio de campamento.</li>
  <li><b>Lectura Secreta:</b> El primer representante corre 10 metros hasta la mesa de jueces y memoriza su tarjeta de mímica.</li>
  <li><b>Dramatización en Silencio:</b> El scout regresa frente a su grupo y actúa la acción sin emitir ningún sonido ni mover los labios.</li>
  <li><b>Adivinación y Relevo:</b> Cuando la patrulla exclama la respuesta correcta, el scout choca la mano de su compañero para darle la salida.</li>
  <li><b>Cómputo Final:</b> La primera patrulla en adivinar todas sus mímicas completa la prueba y obtiene el reconocimiento en el Tally.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Gran Carrera de Mímica Scout</h2>
<p>La actividad valora la expresividad no verbal y la velocidad en el Tally:</p>
<ul>
  <li><b>Mayor Precisión Kinésica:</b> Otorgar 5 puntos a la patrulla cuyo mímico transmita los detalles de la escena con mayor claridad.</li>
  <li><b>Velocidad de Deducción:</b> Otorgar 3 puntos al equipo que descifre las tarjetas en el menor tiempo.</li>
  <li><b>Silencio Impecable:</b> Otorgar 3 puntos a los mímicos que mantengan el silencio total sin emitir ruidos.</li>
</ul>', '/uploads/la-gran-carrera-de-mimica-scout.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Mímica"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular la agilidad mental", "Trabajo en equipo", "Crear un ambiente de distensión"], "justificacion_areas": "La Gran Carrera de Mímica Scout potencia la creatividad al exigir la traducción inmediata de conceptos a gestos kinésicos originales. Desarrolla la sociabilidad al afianzar la empatía no verbal, el trabajo colaborativo en posta y la comunicación fluida en la patrulla.", "variaciones": "<b>Mímica con Pañolín Cruzado:</b> Realizar las señas sujetando los extremos del pañolín scout en todo momento.<br><b>Mímica de Sombras Nocturnas:</b> Actuar detrás de un telón iluminado con linterna en la fogata.<br><b>Edición Películas de Campamento:</b> Representar escenas clásicas de la historia cinematográfica y scout.", "recomendaciones": "Mantener tarjetas variadas según el nivel de la unidad. Fomentar el respeto y evitar la frustración si una escena tarda en ser adivinada.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando atentamente los gestos del mímico para descifrar la tarjeta secreta."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Traduciendo velozmente las acciones escritas en señas kinésicas divertidas."}, {"id": "12686e7d-d6af-4c74-928d-c859d5b883d5", "area": "Creatividad", "unidad": "Compañía", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Proponiendo códigos de señas tácticos para optimizar el tiempo de adivinación."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Interpretando los movimientos desde la perspectiva de las compañeras de equipo."}, {"id": "e465926e-deed-4341-956f-047f56860e5e", "area": "Creatividad", "unidad": "Tropa", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Coordinando la estrategia de adivinación rápida en la patrulla."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando señas abstractas para representar conceptos complejos."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando la regla de silencio total durante la actuación de mímica."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Apoyando al mímico con entusiasmo y sin generar presiones."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Construyendo un ambiente de aliento constante en la patrulla."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fomentando la desinhibición social y la participación equitativa."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando juego limpio y respeto por los tiempos de adivinación del rival."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la camaradería y la empatía en la competencia."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

